PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(user_id INTEGER PRIMARY KEY, loyalty_name TEXT NOT NULL DEFAULT 'MonaPoints', monacoins_per_unit INTEGER NOT NULL DEFAULT 100, tts_enabled INTEGER NOT NULL DEFAULT 1, moderation_mode TEXT NOT NULL DEFAULT 'balanced', theme TEXT NOT NULL DEFAULT 'neon', FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS platforms(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,platform TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,connected INTEGER NOT NULL DEFAULT 0,display_name TEXT DEFAULT '',config_json TEXT NOT NULL DEFAULT '{}',UNIQUE(user_id,platform),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS alerts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,event_type TEXT NOT NULL,name TEXT NOT NULL,platform TEXT NOT NULL DEFAULT 'all',enabled INTEGER NOT NULL DEFAULT 1,duration_ms INTEGER NOT NULL DEFAULT 6000,min_value REAL NOT NULL DEFAULT 0,template TEXT NOT NULL DEFAULT '{user} apoyó con {amount}',media_url TEXT DEFAULT '',sound_url TEXT DEFAULT '',tts INTEGER NOT NULL DEFAULT 0,voice TEXT DEFAULT 'es-ES',font_family TEXT DEFAULT 'Inter',font_size INTEGER NOT NULL DEFAULT 48,font_weight INTEGER NOT NULL DEFAULT 700,text_color TEXT NOT NULL DEFAULT '#ffffff',accent_color TEXT NOT NULL DEFAULT '#ff3bd4',position_x REAL NOT NULL DEFAULT 50,position_y REAL NOT NULL DEFAULT 50,animation TEXT NOT NULL DEFAULT 'pop',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,platform TEXT NOT NULL,event_type TEXT NOT NULL,user_name TEXT NOT NULL DEFAULT 'Viewer',amount REAL NOT NULL DEFAULT 0,unit TEXT NOT NULL DEFAULT '',message TEXT NOT NULL DEFAULT '',payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,processed INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sounds(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS rewards(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,name TEXT NOT NULL,cost INTEGER NOT NULL DEFAULT 100,type TEXT NOT NULL DEFAULT 'sound',payload_json TEXT NOT NULL DEFAULT '{}',enabled INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS timers(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL UNIQUE,name TEXT NOT NULL DEFAULT 'MonaTimer',enabled INTEGER NOT NULL DEFAULT 1,initial_seconds INTEGER NOT NULL DEFAULT 600,max_seconds INTEGER NOT NULL DEFAULT 3600,seconds_per_monacoin REAL NOT NULL DEFAULT 0.1,auto_start INTEGER NOT NULL DEFAULT 0,show_label INTEGER NOT NULL DEFAULT 1,label TEXT NOT NULL DEFAULT 'MonaTimer',position_x REAL NOT NULL DEFAULT 50,position_y REAL NOT NULL DEFAULT 15,font_family TEXT NOT NULL DEFAULT 'Inter',font_size INTEGER NOT NULL DEFAULT 56,text_color TEXT NOT NULL DEFAULT '#ffffff',accent_color TEXT NOT NULL DEFAULT '#ff35d1',end_at INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id));

