CREATE TABLE IF NOT EXISTS media_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,url TEXT NOT NULL,requester TEXT NOT NULL DEFAULT 'Viewer',cost_points INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending',duration_limit INTEGER NOT NULL DEFAULT 600,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS chat_settings(user_id INTEGER PRIMARY KEY,enabled INTEGER NOT NULL DEFAULT 1,show_twitch INTEGER NOT NULL DEFAULT 1,show_youtube INTEGER NOT NULL DEFAULT 1,show_kick INTEGER NOT NULL DEFAULT 1,show_tiktok INTEGER NOT NULL DEFAULT 1,moderation_mode TEXT NOT NULL DEFAULT 'balanced',blocked_words TEXT NOT NULL DEFAULT '',FOREIGN KEY(user_id) REFERENCES users(id));
